query IssueConnection($owner: String!, $name: String!, $number: Int!, $first: Int!, $after: String) {
  repository(owner: $owner, name: $name) {
    issue(number: $number) {
      blockedBy(first: $first, after: $after) { pageInfo { hasNextPage endCursor } nodes { number title state repository { name owner { __typename login } } } }
    }
  }
}

